#!/usr/bin/env python3
"""Write adjudications.json from the current review queue. Reasons are keyed by (page, check); the script refuses to
run if the queue has a diagnostic without a written reason or if a diagnostic payload differs from what was reviewed."""
import json
from pagelib import D, R
W = R / "paper-review/hashemi2023data-paper"
ML, ND, IP = "missing_lines", "number_differences", "independent_parser_number_differences"
WORDS = (" The prose words of every listed line were found in order in the page text (linecheck.py), and a word-multiset "
         "comparison of the page against pdftotext (wordcheck.py) shows no source word missing apart from glued math tokens "
         "such as 'kstep', 'dtrain', 'dtest'.")
